head.script:
scwin.onpageload = function() {
    window.data = [];
    for (var i = 0; i < 100; i++) {
        window.v = ["a", "A", "x", "X"];
        data.push("col1_" + v[i % 4] + "_" + i);
        data.push("col2_" + v[i % 4] + "_" + i);
        data.push("col3_" + v[i % 4] + "_" + i);
    }
    dataList1.setData(data);
}		
scwin.trigger1_onclick = function(e) {
    var ret = dataList1.getMatchedJSON("col1", "A", false);
    textarea1.setValue(JSON.stringify(ret));
};
scwin.trigger2_onclick = function(e) {
    dataList1.setMatchIgnoreCase(true);
};
scwin.trigger3_onclick = function(e) {
    dataList1.setMatchIgnoreCase(false);
};
scwin.checkValue = function() {
    var json = JSON.parse(WebSquare.wUnit.getJq("#textarea1").val());
    for (i = 0; i < json.length; i++) {
        var character = json[i].col1.charAt(5);
        if (i % 2 == 0) {
            if (character == character.toLowerCase()) {
                return true;
            } else {
                return false;
                break;
            }
        } else {
            if (character == character.toUpperCase()) {
                return true;
            } else {
                return false;
                break;
            }
        }
    }
}
scwin.checkUpper = function() {
    var json = JSON.parse(WebSquare.wUnit.getJq("#textarea1").val());
    for (i = 0; i < json.length; i++) {
        var character = json[i].col1.charAt(5);
        if (character == character.toUpperCase()) {
            return true;
        } else {
            return false;
            break;
        }
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkUpper()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
